            conn.execute("ROLLBACK")
            return None, False
        if order["status"] == "rejected":
            conn.execute("ROLLBACK")
            raise RefundError("order_state", "order is rejected and cannot be refunded")

        existing = _fetch_by_request(conn, tenant, refund_request_id)
